// Classe chaque tâche en retard / aujourd'hui / demain (timezone America/Toronto),
// ignore les tâches dont l'échéance est plus lointaine, puis regroupe par user_id.
// Les tâches déjà 'done' sont exclues en amont par la requête Supabase (status=neq.done).
const items = $input.all().map((i) => i.json);

const tz = "America/Toronto";

function dateStr(d) {
  // Convertit une date/heure absolue en chaîne YYYY-MM-DD selon le fuseau
  // Toronto, quel que soit le fuseau horaire du serveur qui exécute ce code.
  return new Date(d).toLocaleDateString("en-CA", { timeZone: tz });
}

function addDaysToDateStr(ymd, days) {
  // Arithmétique purement calendaire (Y-M-D) sur une chaîne déjà exprimée
  // dans le fuseau Toronto : Date.setDate() opère en heure locale du
  // serveur (pas forcément Toronto), donc on manipule uniquement des
  // composants Y-M-D via Date.UTC pour rester indépendant du fuseau serveur.
  const [y, m, d] = ymd.split("-").map(Number);
  const utcDate = new Date(Date.UTC(y, m - 1, d));
  utcDate.setUTCDate(utcDate.getUTCDate() + days);
  return utcDate.toISOString().slice(0, 10);
}

const todayStr = dateStr(new Date());
const tomorrowStr = addDaysToDateStr(todayStr, 1);

const byUser = {};

for (const task of items) {
  if (!task.due_date) continue;
  const due = dateStr(task.due_date);
  let bucket = null;
  if (due < todayStr) bucket = "overdue";
  else if (due === todayStr) bucket = "today";
  else if (due === tomorrowStr) bucket = "tomorrow";
  else continue; // hors périmètre du rappel (échéance plus lointaine)

  if (!byUser[task.user_id]) {
    byUser[task.user_id] = { user_id: task.user_id, overdue: [], today: [], tomorrow: [] };
  }
  byUser[task.user_id][bucket].push({
    title: task.title,
    priority: task.priority,
    due_date: task.due_date,
    project_title: (task.projects && task.projects.title) || "Non renseigné",
  });
}

// Seuls les utilisateurs ayant au moins une tâche pertinente (retard/aujourd'hui/demain)
// sont présents ici : un utilisateur sans échéance pertinente ne reçoit aucun e-mail.
return Object.values(byUser).map((u) => ({ json: u }));

// Construit le récapitulatif HTML pour un utilisateur, à partir des listes
// regroupées (retard/aujourd'hui/demain) et de l'e-mail récupéré via Auth admin.
const authUser = $input.item.json; // { email, ... } via le nœud 'Récupérer l'e-mail Auth'
const grouped = $node["Regrouper par utilisateur"].json; // item courant, même index de branche

const appBaseUrl = $env.APP_BASE_URL || "";
const priorityLabels = { low: "Basse", medium: "Moyenne", high: "Haute" };

function renderList(tasks) {
  if (!tasks || tasks.length === 0) return "<p style=\"color:#888;\">Aucune</p>";
  const items = tasks
    .map(
      (t) =>
        `<li><strong>${t.title}</strong> — ${t.project_title} (priorité : ${priorityLabels[t.priority] || t.priority}, échéance : ${new Date(t.due_date).toLocaleDateString("fr-CA")})</li>`
    )
    .join("");
  return `<ul>${items}</ul>`;
}

const linkHtml = appBaseUrl
  ? `<p><a href="${appBaseUrl}/tasks" style="color:#2563eb;">Voir mes tâches dans ProjectFlow</a></p>`
  : "";

const html = `
  <div style="font-family:Arial,sans-serif;color:#111;max-width:560px;">
    <h2 style="color:#2563eb;">ProjectFlow — Rappel d'échéance</h2>
    <h3>En retard</h3>
    ${renderList(grouped.overdue)}
    <h3>Échéance aujourd'hui</h3>
    ${renderList(grouped.today)}
    <h3>Échéance demain</h3>
    ${renderList(grouped.tomorrow)}
    ${linkHtml}
    <p style="color:#888;font-size:12px;">Cet e-mail est un canal complémentaire aux notifications internes ProjectFlow.</p>
  </div>
`;

return [{ json: { email: authUser.email, subject: "ProjectFlow — Rappel d'échéance", html } }];
